import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DirectionalLight } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Band dimensions
  const bandWidth = 6.8;
  const bandHeight = 2.0;

  const group = new Group();

  // --- Band plane with vertical gradient ---
  const bandGeo = new PlaneGeometry(bandWidth, bandHeight);
  const bandMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    side: THREE.DoubleSide,
    // Ensure gradient is visible even in low light – no emissive to keep it dark
  });

  // Gradient from #121218 (bottom, uv.y=0) to #0b0b10 (top, uv.y=1)
  const colorBottom = new Color('#121218');
  const colorTop = new Color('#0b0b10');
  bandMat.colorNode = mix(
    vec3(colorBottom.r, colorBottom.g, colorBottom.b),
    vec3(colorTop.r, colorTop.g, colorTop.b),
    uv().y
  );

  const bandMesh = new Mesh(bandGeo, bandMat);
  bandMesh.position.z = 0;
  group.add(bandMesh);

  // --- Grazing key light from upper left ---
  // Positioned to skim the surface so hairline rules catch specular edge
  const keyLight = new DirectionalLight(0xffffff, 0.8); // slightly reduced to avoid washout
  keyLight.position.set(2.5, 2.5, 0.5); // shallow angle, near z-axis
  keyLight.target.position.set(0, 0, 0);
  group.add(keyLight);
  group.add(keyLight.target);

  // --- Top hairline rule (full width, 0.006 height) ---
  const hairlineGeo = new BoxGeometry(bandWidth, 0.006, 0.01);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new Color('#23232b'),
    roughness: 0.5,
    metalness: 0.3,
    emissive: new Color('#23232b'),
    emissiveIntensity: 0.1, // subtle glow to ensure visibility
  });
  const topHair = new Mesh(hairlineGeo, hairlineMat);
  topHair.position.set(0, bandHeight / 2 - 0.003, 0.005);
  group.add(topHair);

  // --- Bottom hairline rule (0.25 clearance above bottom edge) ---
  const bottomHair = new Mesh(hairlineGeo.clone(), hairlineMat.clone());
  bottomHair.position.set(0, -bandHeight / 2 + 0.25 + 0.003, 0.005);
  group.add(bottomHair);

  // --- Accent bar (0.3w x 0.02h, emissive #ff2a38) ---
  const accentGeo = new BoxGeometry(0.3, 0.02, 0.01);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.2,
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  // Position: left block spans 2.0 units from left edge (x=-3.4 to -1.4)
  // Wordmark will be at x=-3.4+0.5 = -2.9, accent bar below it at x=-2.9 + 0.15 = -2.75
  accentBar.position.set(-2.65, 0.55, 0.005); // adjusted to sit below wordmark
  group.add(accentBar);

  // --- Text layout (baseline grid 0.25 units) ---
  // Left block: x from -3.4 to -1.4, wordmark at left, accent bar below it
  const wordmarkX = -2.9;
  const wordmarkY = 0.75; // lowered to avoid clipping

  // Column positions: three columns each 1.2w, gutters 0.375 (1.5x base)
  // Starting x = -1.4 (right edge of left block)
  const colStarts = [-1.4, -0.8, 0.775, 2.35]; // actually three columns: centers at -0.8, 0.775, 2.35
  // We'll use an array of center positions
  const colCenters = [-0.8, 0.775, 2.35];
  const colHeaderY = 0.55;
  const linkStepY = 0.13 * 1.8; // line height for links (fontSize 0.13)

  // Font sizes in scene units (em heights)
  const fontSizeWordmark = 0.34; // to fit within band (0.34 height, top at 0.75+0.17=0.92 < 1.0)
  const fontSizeColumnHeader = 0.09;
  const fontSizeLink = 0.13;
  const fontSizeLegal = 0.09;

  let colIndex = -1;
  let linkIndex = 0;
  const linkObjects = [];

  items.forEach((item) => {
    const role = item.role;
    const text = item.text;
    if (!role) return;

    // Determine font size based on role
    let fontSize;
    let align = 'left';
    let color = '#e8ecf2';
    let letterSpacing = 0;
    let maxWidth = bandWidth;

    if (role === 'wordmark') {
      fontSize = 0.34;
      letterSpacing = 0.02;
      color = '#e8ecf2';
    } else if (role === 'column-header') {
      fontSize = 0.09;
      letterSpacing = 0.12;
      color = '#e8ecf2';
      maxWidth = 1.2;
    } else if (role === 'link') {
      fontSize = 0.13;
      letterSpacing = 0;
      color = '#e8ecf2';
      maxWidth = 1.2;
    } else if (role === 'legal') {
      fontSize = 0.09;
      letterSpacing = 0.04;
      align = 'center';
      color = '#e8ecf2';
      maxWidth = bandWidth;
    } else {
      return;
    }

    const textObj = ctx.fontAtlas.createText(text, {
      fontSize: fontSize,
      letterSpacingPx: letterSpacing,
      align: align,
      color: color,
      maxWidthPx: maxWidth,
    });

    if (role === 'wordmark') {
      textObj.position.set(wordmarkX, wordmarkY, 0.005);
    } else if (role === 'column-header') {
      colIndex++;
      linkIndex = 0;
      const x = colCenters[colIndex];
      textObj.position.set(x, colHeaderY, 0.005);
    } else if (role === 'link') {
      const x = colCenters[colIndex];
      const y = colHeaderY - 0.09 * 1.2 - (linkIndex + 1) * linkStepY;
      textObj.position.set(x, y, 0.005);
      linkIndex++;
      linkObjects.push(textObj);
    } else if (role === 'legal') {
      textObj.position.set(0, -0.625, 0.005);
    }

    group.add(textObj);
  });

  // --- Link hover interactions ---
  const linkTimelines = {};
  linkObjects.forEach((obj) => {
    const originalColor = new Color('#e8ecf2');
    const hoverColor = new Color('#ff2a38');
    const meshes = [];
    obj.traverse(child => {
      if (child.isMesh) {
        meshes.push(child);
        child.material.transparent = true;
        child.material.needsUpdate = true;
      }
    });

    const onEnter = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(meshes.map(m => m.material.color), {
        r: hoverColor.r,
        g: hoverColor.g,
        b: hoverColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true,
      });
      gsap.to(obj.position, {
        z: 0.02,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true,
      });
      linkTimelines[obj.uuid] = tl;
    };

    const onLeave = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(meshes.map(m => m.material.color), {
        r: originalColor.r,
        g: originalColor.g,
        b: originalColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true,
      });
      gsap.to(obj.position, {
        z: 0,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true,
      });
      linkTimelines[obj.uuid] = tl;
    };

    obj.userData.handlers = {
      pointerenter: onEnter,
      pointerleave: onLeave,
    };
  });

  // --- Entrance animation: fade-up of the whole colophon ---
  // Gather all materials that need opacity animation (including band, hairline, accent, text meshes)
  const allMaterials = [];
  group.traverse(child => {
    if (child.isMesh && child.material) {
      child.material.transparent = true;
      child.material.needsUpdate = true;
      allMaterials.push(child.material);
    }
  });

  // Start invisible and displaced
  allMaterials.forEach(mat => { mat.opacity = 0; });
  group.position.y = 0.2;

  const enterTL = gsap.timeline({
    paused: true,
    onComplete: () => {
      allMaterials.forEach(mat => { mat.opacity = 1; });
      group.position.y = 0;
    }
  });

  // Animate opacity of all materials simultaneously
  allMaterials.forEach(mat => {
    enterTL.to(mat, { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
  });
  // Animate position
  enterTL.to(group.position, { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);

  enterTL.play();

  // --- Cleanup ---
  const disposeList = [
    bandGeo, bandMat, bandMesh,
    hairlineGeo, topHair, bottomHair,
    accentGeo, accentMat, accentBar,
    ...group.children.filter(c => c.geometry && c.geometry !== bandGeo && c.geometry !== hairlineGeo && c.geometry !== accentGeo)
  ];

  group.userData.cleanup = () => {
    enterTL.kill();
    Object.values(linkTimelines).forEach(tl => tl && tl.kill());
    group.remove(keyLight);
    group.remove(keyLight.target);
    disposeList.forEach(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
      if (obj.children) {
        obj.traverse(child => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      }
    });
  };

  return group;
}
